const amap = (q) => `https://uri.amap.com/search?keyword=${encodeURIComponent(q)}&view=map&src=chengdu-trip&callnative=1`;
const baidu = (q) => `https://www.baidu.com/s?wd=${encodeURIComponent(q)}`;
const photoPath = (f) => `./assets/photos/${f}`;

const foodMediaUrl = (key) => {
  const m = FOOD_MEDIA[key];
  return m?.localFile ? photoPath(m.localFile) : (m?.imageUrl || '');
};
const foodSource = (key) => {
  const m = FOOD_MEDIA[key];
  if (!m) return '';
  return `<a class="photo-source" href="${esc(m.sourcePage)}" target="_blank" rel="noopener noreferrer">攝影：${esc(m.author)} · ${esc(m.license)}</a>`;
};

const esc = (v) => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

function sourceLink(file, compact=false) {
  const c = PHOTO_CREDITS[file];
  if (!c) return '';
  return `<a class="photo-source" href="${esc(c.sourceUrl)}" target="_blank" rel="noopener noreferrer">${compact?'來源':'來源：Wikimedia Commons'}</a>`;
}
function photoFigure(file, caption, cls='') {
  const c = PHOTO_CREDITS[file];
  return `<figure class="photo-card ${cls}"><img src="${photoPath(file)}" alt="${esc(c?.caption || caption)}" loading="lazy"><figcaption><strong>${esc(caption)}</strong>${sourceLink(file,true)}</figcaption></figure>`;
}
function externalLink(label, query) {
  const url = label.startsWith('百度') ? baidu(query) : amap(query);
  return `<a href="${url}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`;
}

const tabs = [...document.querySelectorAll('.nav-tab')];
const views = [...document.querySelectorAll('.view')];
tabs.forEach(tab => tab.addEventListener('click', () => {
  tabs.forEach(x=>x.classList.remove('is-active')); views.forEach(x=>x.classList.remove('is-visible'));
  tab.classList.add('is-active'); document.getElementById(tab.dataset.view)?.classList.add('is-visible');
  if (tab.dataset.view === 'tempo') renderTempo();
  if (innerWidth < 820) scrollTo({top:0,behavior:'smooth'});
}));


