const MAP_ROUTES = [{"name": "川西段", "className": "route-west", "points": ["chengdu", "dujiangyan", "chuanzhusi", "huanglong", "jiuzhaigou", "songpan", "chengdu"]}, {"name": "樂山峨眉段", "className": "route-south", "points": ["chengdu", "leshan", "emei", "chengdu"]}, {"name": "下午擇一", "className": "route-option", "points": ["chengdu", "qingcheng"]}, {"name": "下午擇一", "className": "route-option", "points": ["chengdu", "sanxingdui"]}];

function routeSegmentLines(route) {
  return route.points.slice(0, -1).map((key, index) => {
    const a = MAP_POINTS[key];
    const b = MAP_POINTS[route.points[index + 1]];
    return `<line class="map-route ${route.className}" x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" marker-end="url(#arrow-${route.className})" />`;
  }).join('');
}

function routePointMarker(key) {
  const p = MAP_POINTS[key];
  const palette = {
    city: ['#173d36', '#fff8e9'],
    west: ['#3f8f82', '#effaf6'],
    south: ['#c27a3d', '#fff7e9'],
    option: ['#8062bd', '#f6f0ff'],
  }[p.region];
  const boxWidth = key === 'chengdu' ? 155 : 130;
  const boxX = p.labelX;
  const boxY = p.labelY - 24;
  const connectX = boxX > p.x ? boxX : boxX + boxWidth;
  return `<g class="map-point map-point-${p.region}">
    <line class="map-label-line" x1="${p.x}" y1="${p.y}" x2="${connectX}" y2="${p.labelY}" />
    <circle cx="${p.x}" cy="${p.y}" r="17" fill="${palette[1]}" stroke="${palette[0]}" stroke-width="5" />
    <circle cx="${p.x}" cy="${p.y}" r="6" fill="${palette[0]}" />
    <rect x="${boxX}" y="${boxY}" width="${boxWidth}" height="49" rx="13" fill="#fffdf7" stroke="${palette[0]}" stroke-width="2" />
    <text x="${boxX + 12}" y="${boxY + 20}" font-size="17" font-weight="850" fill="#173d36">${p.name}</text>
    <text x="${boxX + 12}" y="${boxY + 39}" font-size="11.5" font-weight="700" fill="#68716c">${p.days}</text>
  </g>`;
}

function routeMapSvg() {
  return `<figure class="route-image-wrap">
    <a class="route-image-link" href="./assets/maps/route-map-clear.png" target="_blank" rel="noopener">
      <img class="route-image" src="./assets/maps/route-map-clear.png" alt="成都旅途景點相對位置示意圖">
    </a>
    <figcaption class="route-image-caption">點圖片可另開大圖查看。成都位於行程中心，川西段在西北方向，樂山與峨眉山在南方，青城山與三星堆位於成都周邊。</figcaption>
  </figure>`;
}

function renderTempo() {
  const timeGrid = document.getElementById('timeGrid');
  const routeMap = document.getElementById('routeMap');
  if (!timeGrid || !routeMap) return;
  timeGrid.innerHTML = TIME_PLAN.map(day => `
    <article class="time-card">
      <div class="time-card-head"><div><span class="card-kicker">${esc(day.date)}</span><h5>${esc(day.title)}</h5></div><span class="tag">${esc(day.highlight)}</span></div>
      <div class="mini-table-wrap"><table class="mini-table"><thead><tr><th>時間</th><th>該到哪裡</th><th>重點</th></tr></thead><tbody>
        ${day.rows.map(row => `<tr><td>${esc(row[0])}</td><td>${esc(row[1])}</td><td>${esc(row[2])}</td></tr>`).join('')}
      </tbody></table></div>
    </article>
  `).join('');
  routeMap.innerHTML = routeMapSvg();
}

let selectedDay = 0;
function renderDateSwitcher() {
  const el = document.getElementById('dateSwitcher');
  el.innerHTML = ITINERARY.map((d,i)=>`<button class="date-button ${i===selectedDay?'is-active':''}" data-i="${i}">${esc(d.date)}</button>`).join('');
  el.querySelectorAll('button').forEach(b=>b.onclick=()=>{selectedDay=+b.dataset.i;renderDateSwitcher();renderDay();});
}
function renderDay() {
  const d=ITINERARY[selectedDay], el=document.getElementById('dayPanel');
  const stay=HOTELS.find(x=>x.date===d.date);
  el.innerHTML=`<div class="day-title"><div><p class="eyebrow">${esc(d.weekday)} · ${esc(d.date)}</p><h4>${esc(d.title)}</h4></div><span class="tag">${esc(d.theme)}</span></div>
  ${dailyPlaceGuides(d.date)}
  <div class="day-photo-grid">${d.photos.map((f,i)=>photoFigure(f, PHOTO_CREDITS[f]?.caption || d.title)).join('')}</div>
  ${DAY_FOOD[d.date] ? `<section class="today-food"><div><p class="eyebrow">今日吃什麼</p><h5>${esc(DAY_FOOD[d.date].title)}</h5><p>${esc(DAY_FOOD[d.date].body)}</p></div><div class="food-chip-row">${DAY_FOOD[d.date].chips.map(x=>`<span class="food-chip">${esc(x)}</span>`).join('')}</div></section>` : ''}
  ${stay ? `<section class="today-stay"><div><p class="eyebrow">今晚住宿</p><h5>${esc(stay.name)}</h5><p>${esc(stay.area)} · ${esc(stay.status)}</p></div>${stay.query ? `<div class="link-row">${externalLink('高德地圖',stay.query)}</div>` : ''}</section>` : ''}
  <div class="timeline">${d.items.map(item=>`<article class="timeline-item"><div class="timeline-time">${esc(item[0])}</div><div><h5>${esc(item[1])}</h5><p>${esc(item[2])}</p><div class="link-row">${item[3].map(x=>externalLink(x[0],x[1])).join('')}</div></div></article>`).join('')}</div>`;
}

let placeFilter = '全部';
let placeDay = '';
let placeQuery = '';

// Fold common simplified spellings so either keyboard can find the same guide.
function normalizePlaceText(value) {
  const pairs = {'区':'區','龙':'龍','沟':'溝','乐':'樂','庙':'廟','国':'國','园':'園','宽':'寬','锦':'錦','里':'里','抚':'撫','楼':'樓','观':'觀','堆':'堆','湾':'灣','戏':'戲','剧':'劇','脸':'臉','猫':'貓','镇':'鎮','门':'門','栈':'棧','层':'層','绵':'綿','兴':'興','县':'縣','际':'際'};
  return String(value || '').toLowerCase().replace(/[区龙沟乐庙国园宽锦抚楼观湾戏剧脸猫镇门栈层绵兴县际]/g, c => pairs[c]).replace(/\s+/g, ' ').replaceAll('奎興樓街', '奎星樓街').trim();
}

function guideSourceUrl(value) {
  try {
    const url = new URL(value);
    return ['https:', 'http:'].includes(url.protocol) ? url.href : '#';
  } catch { return '#'; }
}

function guideCard(place) {
  const number = String(PLACES.findIndex(x => x.id === place.id) + 1).padStart(2, '0');
  const picture = place.photo ? `<figure class="guide-photo">
    <img src="${photoPath(place.photo)}" alt="${esc(place.photoCaption)}" loading="lazy" decoding="async">
    <figcaption><span>${esc(place.photoCaption)}</span>${sourceLink(place.photo, true)}</figcaption>
  </figure>` : '';
  return `<article class="guide-card ${place.optionGroup ? 'guide-option' : ''} ${!place.photo ? 'guide-text-card' : ''}" id="place-${esc(place.id)}" aria-labelledby="guide-title-${esc(place.id)}">
    ${picture}
    <div class="guide-body">
      <div class="guide-meta"><span class="guide-number">${number}</span><span>${esc(place.area)}</span><span class="guide-status">${esc(place.status)}</span></div>
      <h4 class="guide-title" id="guide-title-${esc(place.id)}" tabindex="-1">${esc(place.name)}</h4>
      <p class="guide-tagline">${esc(place.tagline)}</p>
      <div class="guide-date-row">${place.dates.map(date => `<span>${esc(date)}</span>`).join('')}<span class="guide-region">${esc(place.group)}</span></div>
      <div class="guide-trip"><span>這次安排</span><p>${esc(place.tripPlan)}</p></div>
      <p class="guide-intro">${esc(place.intro)}</p>
      <div class="guide-highlights" aria-label="看什麼">${place.highlights.map((h, i) => `<div class="guide-highlight"><span>${i + 1}</span><div><h5>${esc(h.title)}</h5><p>${esc(h.body)}</p></div></div>`).join('')}</div>
      <details class="guide-details">
        <summary>玩法、停留與提醒</summary>
        <div class="guide-detail-body">
          <section><h5>建議怎麼玩</h5><p>${esc(place.routeAdvice)}</p></section>
          <section class="guide-duration"><h5>時間建議</h5><p>${esc(place.duration)}</p><small>停留建議，不是已確認的集合或預約時刻。</small></section>
          <section class="guide-reminder"><h5>出發前留意</h5><p>${esc(place.reminder)}</p></section>
          <div class="guide-sources"><h5>景點資料來源</h5>${place.sources.map(s => `<a href="${esc(guideSourceUrl(s.url))}" target="_blank" rel="noopener noreferrer">${esc(s.label)} ↗</a>`).join('')}</div>
        </div>
      </details>
      <div class="guide-actions">
        <a class="guide-map-link" href="${amap(place.query)}" target="_blank" rel="noopener noreferrer">${esc(place.mapLabel || '高德地圖')} ↗</a>
        ${place.dates.map(date => `<button type="button" data-guide-day="${esc(date)}">看 ${esc(date)} 行程</button>`).join('')}
      </div>
    </div>
  </article>`;
}

function renderPlaceCards() {
  const grid = document.getElementById('placesGrid');
  if (!grid) return;
  const q = normalizePlaceText(placeQuery);
  const rows = PLACES.filter(place =>
    (placeFilter === '全部' || place.group === placeFilter) &&
    (!placeDay || place.dates.includes(placeDay)) &&
    (!q || normalizePlaceText([place.name, place.tagline, place.area, place.intro, place.query,
      ...place.highlights.flatMap(h => [h.title, h.body])].join(' ')).includes(q))
  );
  grid.innerHTML = rows.length ? rows.map(guideCard).join('') : `<div class="guide-empty"><h4>這個條件沒有符合的景點</h4><p>可以換一個關鍵字、日期或地區；9/27 是返程日，沒有另列景點。</p><button type="button" data-reset-guides>顯示全部景點</button></div>`;
  document.getElementById('placesCount').textContent = `顯示 ${rows.length}／${PLACES.length} 處${placeDay ? ' · '+placeDay : ''}${placeFilter !== '全部' ? ' · '+placeFilter : ''}`;
}

function renderPlaces() {
  const filters = document.getElementById('placeFilters');
  if (!filters) return;
  const groups = ['全部', ...new Set(PLACES.map(p => p.group))];
  filters.innerHTML = groups.map(group => `<button type="button" class="filter-pill ${group === placeFilter ? 'is-active' : ''}" data-place-group="${esc(group)}" aria-pressed="${group === placeFilter}">${esc(group)}</button>`).join('');
  filters.querySelectorAll('button').forEach(button => button.onclick = () => {
    placeFilter = button.dataset.placeGroup;
    renderPlaces();
  });
  document.getElementById('placeSearch').value = placeQuery;
  document.getElementById('placeDay').value = placeDay;
  renderPlaceCards();
}

function resetPlaceFilters() {
  placeFilter = '全部'; placeDay = ''; placeQuery = '';
  renderPlaces();
}

function openPlaceGuide(id) {
  if (!PLACES.some(p => p.id === id)) return;
  resetPlaceFilters();
  document.querySelector('[data-view="places"]').click();
  requestAnimationFrame(() => {
    const card = document.getElementById(`place-${id}`);
    if (!card) return;
    card.querySelector('details').open = true;
    card.querySelector('.guide-title').focus({preventScroll:true});
    card.scrollIntoView({block:'start', behavior:'auto'});
  });
}

function dailyPlaceGuides(date) {
  const places = PLACES.filter(p => p.dates.includes(date));
  return places.length ? `<section class="daily-guides" aria-label="這天的景點介紹"><div><span class="eyebrow">到現場看什麼</span><h5>這天的景點介紹</h5></div><div class="daily-guide-links">${places.map(p => `<button type="button" data-open-guide="${esc(p.id)}">${esc(p.name)}${p.optionGroup ? '<span>擇一</span>' : ''}<b aria-hidden="true">↗</b></button>`).join('')}</div></section>` : '';
}

const guideSearchInput = document.getElementById('placeSearch');
const guideDaySelect = document.getElementById('placeDay');
guideSearchInput.addEventListener('input', () => { placeQuery = guideSearchInput.value; renderPlaceCards(); });
guideDaySelect.addEventListener('change', () => { placeDay = guideDaySelect.value; renderPlaces(); });
document.getElementById('placeReset').addEventListener('click', resetPlaceFilters);
document.getElementById('placesGrid').addEventListener('click', event => {
  const button = event.target.closest('button');
  if (!button) return;
  if (button.hasAttribute('data-reset-guides')) { resetPlaceFilters(); return; }
  if (button.dataset.guideDay) {
    const index = ITINERARY.findIndex(d => d.date === button.dataset.guideDay);
    if (index < 0) return;
    selectedDay = index; renderDateSwitcher(); renderDay();
    document.querySelector('[data-view="itinerary"]').click();
    requestAnimationFrame(() => document.getElementById('dayPanel').scrollIntoView({block:'start', behavior:'auto'}));
  }
});
document.getElementById('dayPanel').addEventListener('click', event => {
  const button = event.target.closest('[data-open-guide]');
  if (button) openPlaceGuide(button.dataset.openGuide);
});


function renderHotels() {
  const grid=document.getElementById('hotelGrid');
  if (!grid) return;
  grid.innerHTML=HOTELS.map(h=>`<article class="hotel-card">
    <div class="hotel-date"><span>${esc(h.date)}</span><strong>${esc(h.area)}</strong></div>
    <div class="hotel-main"><span class="card-kicker">${esc(h.status)}</span><h4>${esc(h.name)}</h4>
      <p>${h.status==='返程日'?'當天分兩次送機，不安排住宿。':'酒店名稱依旅行社 9 月 18 日最新版行程表。'}</p>
      ${h.query?`<div class="link-row">${externalLink('高德地圖',h.query)}</div>`:''}
    </div>
  </article>`).join('');
}

let foodFilter='全部';
function renderFood() {
  const groups=['全部',...new Set(FOOD.map(x=>x.category))], filters=document.getElementById('foodFilters');
  filters.innerHTML=groups.map(g=>`<button class="filter-pill ${g===foodFilter?'is-active':''}" data-g="${esc(g)}">${esc(g)}</button>`).join('');
  filters.querySelectorAll('button').forEach(b=>b.onclick=()=>{foodFilter=b.dataset.g;renderFood();});
  const rows=foodFilter==='全部'?FOOD:FOOD.filter(x=>x.category===foodFilter);
  document.getElementById('foodGrid').innerHTML=rows.map(x=>`<article class="place-card food-card">
    <div class="place-photo food-photo"><img src="${foodMediaUrl(x.media)}" alt="${esc(x.name)}" referrerpolicy="no-referrer"><div class="source-float">${foodSource(x.media)}</div></div>
    <div class="place-body"><span class="card-kicker">${esc(x.day)}</span><h4>${esc(x.name)}</h4><p>${esc(x.body)}</p>
    <div class="tag-row"><span class="tag">${esc(x.category)}</span></div>
    <div class="link-row">${externalLink('百度搜尋',x.query)}${externalLink('高德附近',x.query)}</div></div>
  </article>`).join('');
}

async function prefetchFoodPhotos() {
  if (!('caches' in window)) return;
  try {
    const cache = await caches.open('chengdu-food-photos');
    const urls = [...new Set(Object.values(FOOD_MEDIA).filter(x=>x.imageUrl).map(x=>x.imageUrl))];
    await Promise.allSettled(urls.map(async (url) => {
      if (await cache.match(url)) return;
      const response = await fetch(url, {mode:'no-cors'});
      await cache.put(url, response);
    }));
  } catch {}
}

let galleryFilter='全部';
function renderGallery() {
  const groups=['全部',...new Set(GALLERY.map(x=>x[2]))], filters=document.getElementById('galleryFilters');
  filters.innerHTML=groups.map(g=>`<button class="filter-pill ${g===galleryFilter?'is-active':''}" data-g="${esc(g)}">${esc(g)}</button>`).join('');
  filters.querySelectorAll('button').forEach(b=>b.onclick=()=>{galleryFilter=b.dataset.g;renderGallery();});
  const rows=galleryFilter==='全部'?GALLERY:GALLERY.filter(x=>x[2]===galleryFilter);
  document.getElementById('galleryGrid').innerHTML=rows.map((x,i)=>`<figure class="gallery-card ${i%8===0?'gallery-wide':''}"><img src="${photoPath(x[0])}" alt="${esc(x[1])}" loading="lazy"><figcaption><span>${esc(x[2])}</span><strong>${esc(x[1])}</strong>${sourceLink(x[0],true)}</figcaption></figure>`).join('');
}

const NOTES_KEY='chengdu-trip-notes';
const noteForm=document.getElementById('noteForm'), noteList=document.getElementById('noteList');
function getNotes(){try{return JSON.parse(localStorage.getItem(NOTES_KEY)||'[]')}catch{return[]}}
function setNotes(v){localStorage.setItem(NOTES_KEY,JSON.stringify(v))}
function renderNotes(){const n=getNotes();document.getElementById('notesStatus').textContent='備註只會保存在目前使用的手機。';noteList.innerHTML=n.length?n.map(x=>`<article class="note-card"><h4>${esc(x.title)}</h4><p>${esc(x.body)}</p><button data-id="${esc(x.id)}">刪除</button></article>`).join(''):'<article class="note-card"><h4>尚無備註</h4><p>可記錄航班、門票、餐廳、分工與購物清單。</p></article>';}
noteForm.addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(noteForm),n=getNotes();n.unshift({id:crypto.randomUUID?.()||Date.now().toString(),title:String(fd.get('title')).trim(),body:String(fd.get('body')).trim()});setNotes(n);noteForm.reset();renderNotes();});
noteList.addEventListener('click',e=>{const b=e.target.closest('[data-id]');if(!b)return;setNotes(getNotes().filter(x=>x.id!==b.dataset.id));renderNotes();});

renderTempo();renderDateSwitcher();renderDay();renderPlaces();renderHotels();renderFood();renderGallery();renderNotes();prefetchFoodPhotos();
if('serviceWorker' in navigator) addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
